def upgrade() -> None:
    connection = op.get_bind()
    for statement in SCHEMA:
        connection.exec_driver_sql(statement)


def downgrade() -> None:
    connection = op.get_bind()
    for table in reversed(TABLES):
        connection.exec_driver_sql(f'DROP TABLE "{table}"')
